// Batch 12 — World Icons. Source of src/content/batches/batch-12.json (run: node docs/content-research/batch-12.src.cjs).
// Every fact in a story comes from a quoted source sentence; clues and hints are general geography.
const BR = "https://www.britannica.com/";
const entries = [];
// P(entity, question): compact form. url may be a Britannica path or a full https URL.
const P = (id, name, mono, cc, region, sub, q) => entries.push({
 entity: { id, name, monogram: mono, countryOfOrigin: cc, region, ...(q.originNote ? { originNote: q.originNote } : {}) },
 question: { id: q.qid, primaryCategory: "icons", subcategory: sub, questionType: q.type, difficulty: q.diff, displayCategory: q.display ?? "Icons", chapter: q.chapter,
  question: q.question, clue: q.clue, hint: q.hint, answer: { city: q.city, country: q.country, countryCode: q.code, ...(q.geocode ? { geocode: q.geocode } : {}) }, story: q.story,
  ...(q.secondary ? { secondary: q.secondary } : {}),
  sources: q.quotes.map((quote, i) => ({ url: /^https:/.test(q.url) ? q.url : BR + q.url, role: i ? "extra" : "primary", quality: q.quality ?? "reputable_secondary", quote })) },
});

